// Base API client
// ============================================================
const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000";
async function apiFetch(path, options) {
    const res = await fetch(`${API_BASE}${path}`, {
        ...options,
        credentials: "include",
        headers: {
            "Content-Type": "application/json",
            ...options?.headers
        }
    });
    if (!res.ok) {
        const error = await res.json().catch(()=>({
                detail: "Unknown error"
            }));
        throw new Error(error.detail || `HTTP ${res.status}`);
    }
    return res.json();
}
const api = {
    auth: {
        me: ()=>apiFetch("/auth/me"),
        logout: ()=>apiFetch("/auth/logout", {
                method: "POST"
            }),
        loginUrl: ()=>`${API_BASE}/auth/login`
    },
    dashboard: {
        stats: ()=>apiFetch("/api/dashboard/stats")
    },
    disputes: {
        list: (params)=>{
            const qs = params ? `?${new URLSearchParams(params).toString()}` : "";
            return apiFetch(`/api/disputes${qs}`);
        },
        get: (id)=>apiFetch(`/api/disputes/${id}`),
        create: (data)=>apiFetch("/api/disputes", {
                method: "POST",
                body: JSON.stringify(data)
            }),
        update: (id, data)=>apiFetch(`/api/disputes/${id}`, {
                method: "PATCH",
                body: JSON.stringify(data)
            }),
        generateEmail: (id)=>apiFetch(`/api/disputes/${id}/generate-email`, {
                method: "POST"
            }),
        sendEmail: (id, email)=>apiFetch(`/api/disputes/${id}/send-email`, {
                method: "POST",
                body: JSON.stringify(email ?? {})
            }),
        getEmails: (id)=>apiFetch(`/api/disputes/${id}/emails`),
        getPendingDraft: (id)=>apiFetch(`/api/disputes/${id}/pending-draft`),
        approveSend: (id, edited)=>apiFetch(`/api/disputes/${id}/approve-send`, {
                method: "POST",
                body: JSON.stringify(edited ?? {})
            }),
        skip: (id)=>apiFetch(`/api/disputes/${id}/skip`, {
                method: "POST"
            })
    },
    settings: {
        update: (data)=>apiFetch("/api/users/me/settings", {
                method: "PATCH",
                body: JSON.stringify(data)
            }),
        updateApprovalMode: (mode)=>apiFetch("/api/users/me/settings", {
                method: "PATCH",
                body: JSON.stringify({
                    approval_mode: mode
                })
            }),
        validateSheet: (spreadsheetId)=>apiFetch(`/api/sheets/validate?spreadsheet_id=${encodeURIComponent(spreadsheetId)}`)
    }
};
